/** Emotion transient prop convention — same rule as styled-components `$` prefix. */
export const isTransientProp = (prop: string): boolean => prop.startsWith('$');

/** Use as `shouldForwardProp` when `styled()` targets a custom React component. */
export const transientShouldForwardProp = (prop: string): boolean =>
  !isTransientProp(prop);
